// Calls v(<feed message>) for one message of the feed protocol; false if the type is
// unknown or the length does not match it.
template <class V>
bool dispatch_feed(const std::uint8_t* p, std::size_t n, V&& v) {
    if (n == 0) return false;
    switch (p[0]) {
        case 'A': if (n != FeedA::kLength) return false; v(FeedA{p}); return true;
        case 'E': if (n != FeedE::kLength) return false; v(FeedE{p}); return true;
        case 'X': if (n != FeedX::kLength) return false; v(FeedX{p}); return true;
        case 'D': if (n != FeedD::kLength) return false; v(FeedD{p}); return true;
        case 'P': if (n != FeedP::kLength) return false; v(FeedP{p}); return true;
        case 'U': if (n != FeedU::kLength) return false; v(FeedU{p}); return true;
        case 'C': if (n != FeedC::kLength) return false; v(FeedC{p}); return true;
        case 'Q': if (n != FeedQ::kLength) return false; v(FeedQ{p}); return true;
        case 'I': if (n != FeedI::kLength) return false; v(FeedI{p}); return true;
        case 'S': if (n != FeedS::kLength) return false; v(FeedS{p}); return true;
        case 'H': if (n != FeedH::kLength) return false; v(FeedH{p}); return true;
        case 'R': if (n != FeedR::kLength) return false; v(FeedR{p}); return true;
        case 'G': if (n != FeedG::kLength) return false; v(FeedG{p}); return true;
        case 'W': if (n != FeedW::kLength) return false; v(FeedW{p}); return true;
        default: return false;
    }
}

