// Calls v(<out message>) for one message of the out protocol; false if the type is
// unknown or the length does not match it.
template <class V>
bool dispatch_out(const std::uint8_t* p, std::size_t n, V&& v) {
    if (n == 0) return false;
    switch (p[0]) {
        case 'S': if (n != OutS::kLength) return false; v(OutS{p}); return true;
        case 'A': if (n != OutA::kLength) return false; v(OutA{p}); return true;
        case 'U': if (n != OutU::kLength) return false; v(OutU{p}); return true;
        case 'C': if (n != OutC::kLength) return false; v(OutC{p}); return true;
        case 'E': if (n != OutE::kLength) return false; v(OutE{p}); return true;
        case 'J': if (n != OutJ::kLength) return false; v(OutJ{p}); return true;
        default: return false;
    }
}

